tool_use_result.content:
/* ClipCast Design System */
@import url('https://fonts.googleapis.com/css2?family=Inter:wght@400;500;600;700;800&display=swap');

:root {
  --primary: #1868DB;
  --primary-dark: #1351a8;
  --primary-light: #e8f0fd;
  --accent: #FF613D;
  --accent-dark: #e5501f;
  --dark: #292A2E;
  --gray-900: #1a1a1f;
  --gray-800: #2d2d35;
  --gray-700: #45454f;
  --gray-600: #636370;
  --gray-500: #8d8d9a;
  --gray-400: #b5b5c0;
  --gray-300: #d8d8e0;
  --gray-200: #eeeff1;
  --gray-100: #f5f5f7;
  --white: #ffffff;
  --gradient-primary: linear-gradient(135deg, var(--primary) 0%, #7c3aed 100%);
  --gradient-accent: linear-gradient(135deg, var(--accent) 0%, #ff8f6b 100%);
  --gradient-bg: linear-gradient(180deg, #f8faff 0%, #ffffff 100%);
  --shadow-sm: 0 1px 2px rgba(0,0,0,0.05);
  --shadow-md: 0 4px 12px rgba(0,0,0,0.08);
  --shadow-lg: 0 8px 30px rgba(0,0,0,0.12);
  --shadow-xl: 0 20px 50px rgba(0,0,0,0.15);
  --radius-sm: 8px;
  --radius-md: 12px;
  --radius-lg: 16px;
  --radius-xl: 24px;
  --transition: all 0.3s ease;
}

*, *::before, *::after {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

html {
  scroll-behavior: smooth;
}

body {
  font-family: 'Inter', -apple-system, BlinkMacSystemFont, sans-serif;
  font-size: 16px;
  line-height: 1.6;
  color: var(--dark);
  background: var(--white);
  -webkit-font-smoothing: antialiased;
}

img {
  max-width: 100%;
  display: block;
}

a {
  color: inherit;
  text-decoration: none;
}

button {
  font-family: inherit;
  cursor: pointer;
  border: none;
  background: none;
}

.container {
  max-width: 1200px;
  margin: 0 auto;
  padding: 0 24px;
}

/* Typography */
h1, h2, h3, h4, h5, h6 {
  font-weight: 700;
  line-height: 1.2;
}

h1 { font-size: clamp(2.5rem, 5vw, 4rem); }
h2 { font-size: clamp(2rem, 4vw, 3rem); }
h3 { font-size: clamp(1.5rem, 3vw, 2rem); }
h4 { font-size: 1.25rem; }

.text-gradient {
  background: var(--gradient-primary);
  -webkit-background-clip: text;
  -webkit-text-fill-color: transparent;
  background-clip: text;
}

/* Buttons */
.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  padding: 14px 28px;
  font-size: 1rem;
  font-weight: 600;
  border-radius: var(--radius-md);
  transition: var(--transition);
  white-space: nowrap;
}

.btn-primary {
  background: var(--primary);
  color: var(--white);
}

.btn-primary:hover {
  background: var(--primary-dark);
  transform: translateY(-2px);
  box-shadow: var(--shadow-md);
}

.btn-accent {
  background: var(--accent);
  color: var(--white);
}

.btn-accent:hover {
  background: var(--accent-dark);
  transform: translateY(-2px);
  box-shadow: var(--shadow-md);
}

.btn-outline {
  background: transparent;
  border: 2px solid var(--gray-300);
  color: var(--dark);
}

.btn-outline:hover {
  border-color: var(--primary);
  color: var(--primary);
}

.btn-lg {
  padding: 18px 36px;
  font-size: 1.125rem;
}

.btn-sm {
  padding: 10px 20px;
  font-size: 0.875rem;
}

/* Nav */
.navbar {
  position: fixed;
  top: 0;
  left: 0;
  right: 0;
  background: rgba(255,255,255,0.95);
  backdrop-filter: blur(10px);
  z-index: 1000;
  border-bottom: 1px solid var(--gray-200);
}

.navbar .container {
  display: flex;
  align-items: center;
  justify-content: space-between;
  height: 72px;
}

.nav-logo {
  font-size: 1.5rem;
  font-weight: 800;
  color: var(--primary);
  display: flex;
  align-items: center;
  gap: 8px;
}

.nav-logo svg {
  width: 32px;
  height: 32px;
}

.nav-links {
  display: flex;
  align-items: center;
  gap: 32px;
  list-style: none;
}

.nav-links a {
  font-weight: 500;
  color: var(--gray-700);
  transition: var(--transition);
}

.nav-links a:hover {
  color: var(--primary);
}

.nav-actions {
  display: flex;
  align-items: center;
  gap: 16px;
}

/* Sections */
.section {
  padding: 100px 0;
}

.section-sm {
  padding: 60px 0;
}

.section-alt {
  background: var(--gray-100);
}

.section-dark {
  background: var(--gray-900);
  color: var(--white);
}

.section-header {
  text-align: center;
  max-width: 700px;
  margin: 0 auto 60px;
}

.section-header h2 {
  margin-bottom: 16px;
}

.section-header p {
  font-size: 1.125rem;
  color: var(--gray-600);
}

/* Cards */
.card {
  background: var(--white);
  border-radius: var(--radius-lg);
  padding: 32px;
  box-shadow: var(--shadow-md);
  transition: var(--transition);
}

.card:hover {
  transform: translateY(-4px);
  box-shadow: var(--shadow-lg);
}

/* Logo Bar */
.logo-bar {
  padding: 40px 0;
  background: var(--gray-100);
  text-align: center;
}

.logo-bar p {
  font-size: 0.875rem;
  color: var(--gray-500);
  margin-bottom: 24px;
  text-transform: uppercase;
  letter-spacing: 1px;
}

.logo-bar-logos {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 48px;
  flex-wrap: wrap;
}

.logo-bar-logos span {
  font-size: 1.25rem;
  font-weight: 700;
  color: var(--gray-400);
}

/* Hero */
.hero {
  padding: 160px 0 100px;
  background: var(--gradient-bg);
  text-align: center;
}

.hero h1 {
  margin-bottom: 24px;
}

.hero-subtitle {
  font-size: 1.25rem;
  color: var(--gray-600);
  max-width: 600px;
  margin: 0 auto 40px;
}

.hero-actions {
  display: flex;
  gap: 16px;
  justify-content: center;
  flex-wrap: wrap;
}

.hero-stats {
  margin-top: 60px;
  font-size: 0.875rem;
  color: var(--gray-500);
}

/* Feature Highlight */
.feature-highlight {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 60px;
  align-items: center;
}

.feature-highlight-content h2 {
  margin-bottom: 16px;
}

.feature-highlight-content p {
  color: var(--gray-600);
  margin-bottom: 24px;
}

.feature-badge {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  background: var(--accent);
  color: var(--white);
  padding: 6px 12px;
  border-radius: 20px;
  font-size: 0.75rem;
  font-weight: 600;
  text-transform: uppercase;
  margin-bottom: 16px;
}

.feature-image {
  background: var(--primary-light);
  border-radius: var(--radius-xl);
  padding: 40px;
  display: flex;
  align-items: center;
  justify-content: center;
}

/* Screen Recorder */
.screen-recorder {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 60px;
  align-items: center;
}

/* Video Editor */
.video-editor-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 24px;
  margin-top: 48px;
}

.video-editor-item {
  background: var(--white);
  border-radius: var(--radius-lg);
  padding: 24px;
  box-shadow: var(--shadow-sm);
  border: 1px solid var(--gray-200);
}

.video-editor-item h4 {
  margin-bottom: 8px;
}

.video-editor-item p {
  font-size: 0.875rem;
  color: var(--gray-600);
}

/* Integrations */
.integrations-grid {
  display: grid;
  grid-template-columns: repeat(6, 1fr);
  gap: 32px;
  margin-top: 48px;
}

.integration-item {
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 20px;
  background: var(--white);
  border-radius: var(--radius-md);
  border: 1px solid var(--gray-200);
  transition: var(--transition);
}

.integration-item:hover {
  border-color: var(--primary);
  transform: translateY(-2px);
}

/* Security */
.security-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 24px;
  margin-top: 48px;
}

.security-item {
  text-align: center;
  padding: 32px 24px;
  background: var(--white);
  border-radius: var(--radius-lg);
  border: 1px solid var(--gray-200);
}

.security-item h4 {
  margin-top: 16px;
}

/* Use Cases */
.use-cases-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 24px;
  margin-top: 48px;
}

.use-case-item {
  padding: 32px;
  background: var(--white);
  border-radius: var(--radius-lg);
  text-align: center;
  transition: var(--transition);
  border: 1px solid var(--gray-200);
}

.use-case-item:hover {
  border-color: var(--primary);
  transform: translateY(-4px);
}

.use-case-icon {
  width: 56px;
  height: 56px;
  background: var(--primary-light);
  border-radius: var(--radius-md);
  display: flex;
  align-items: center;
  justify-content: center;
  margin: 0 auto 16px;
}

/* Features Grid */
.features-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 24px;
  margin-top: 48px;
}

.feature-item {
  display: flex;
  gap: 16px;
  padding: 24px;
  background: var(--white);
  border-radius: var(--radius-md);
  border: 1px solid var(--gray-200);
}

.feature-icon {
  width: 44px;
  height: 44px;
  background: var(--primary);
  border-radius: var(--radius-sm);
  display: flex;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
}

.feature-icon svg {
  width: 22px;
  height: 22px;
  stroke: var(--white);
}

/* Testimonials */
.testimonials-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 24px;
  margin-top: 48px;
}

.testimonial-card {
  background: var(--white);
  border-radius: var(--radius-lg);
  padding: 32px;
  border: 1px solid var(--gray-200);
}

.testimonial-card p {
  font-size: 1rem;
  line-height: 1.7;
  margin-bottom: 24px;
  color: var(--gray-700);
}

.testimonial-author {
  display: flex;
  align-items: center;
  gap: 12px;
}

.testimonial-avatar {
  width: 48px;
  height: 48px;
  background: var(--gradient-primary);
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
  color: var(--white);
  font-weight: 700;
}

.testimonial-info h5 {
  font-weight: 600;
}

.testimonial-info p {
  font-size: 0.875rem;
  color: var(--gray-500);
  margin-bottom: 0;
}

/* Blog */
.blog-grid {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: 32px;
  margin-top: 48px;
}

.blog-card {
  background: var(--white);
  border-radius: var(--radius-lg);
  overflow: hidden;
  border: 1px solid var(--gray-200);
  transition: var(--transition);
}

.blog-card:hover {
  transform: translateY(-4px);
  box-shadow: var(--shadow-lg);
}

.blog-card-content {
  padding: 24px;
}

.blog-card-label {
  font-size: 0.75rem;
  font-weight: 600;
  color: var(--primary);
  text-transform: uppercase;
  margin-bottom: 8px;
}

.blog-card h4 {
  margin-bottom: 8px;
}

.blog-card p {
  font-size: 0.875rem;
  color: var(--gray-600);
}

/* CTA Banner */
.cta-banner {
  background: var(--gradient-primary);
  color: var(--white);
  text-align: center;
  padding: 80px 24px;
  border-radius: var(--radius-xl);
  margin: 0 24px;
}

.cta-banner h2 {
  margin-bottom: 16px;
}

.cta-banner p {
  font-size: 1.125rem;
  opacity: 0.9;
  margin-bottom: 32px;
}

.cta-banner .btn {
  background: var(--white);
  color: var(--primary);
}

.cta-banner .btn:hover {
  background: var(--gray-100);
}

/* Footer */
.footer {
  background: var(--gray-900);
  color: var(--gray-400);
  padding: 80px 0 40px;
}

.footer-grid {
  display: grid;
  grid-template-columns: 2fr repeat(4, 1fr);
  gap: 48px;
  margin-bottom: 48px;
}

.footer-brand p {
  margin-top: 16px;
  font-size: 0.875rem;
}

.footer h5 {
  color: var(--white);
  margin-bottom: 20px;
  font-size: 0.875rem;
  text-transform: uppercase;
  letter-spacing: 1px;
}

.footer ul {
  list-style: none;
}

.footer ul li {
  margin-bottom: 12px;
}

.footer ul li a:hover {
  color: var(--white);
}

.footer-bottom {
  padding-top: 40px;
  border-top: 1px solid var(--gray-800);
  display: flex;
  justify-content: space-between;
  align-items: center;
  font-size: 0.875rem;
}

.footer-legal {
  display: flex;
  gap: 24px;
}

/* Enterprise Page */
.enterprise-stats {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 32px;
  margin-top: 48px;
}

.enterprise-stat {
  text-align: center;
  padding: 32px;
  background: var(--white);
  border-radius: var(--radius-lg);
  border: 1px solid var(--gray-200);
}

.enterprise-stat h2 {
  font-size: 3rem;
  color: var(--primary);
  margin-bottom: 8px;
}

.enterprise-stat p {
  color: var(--gray-600);
}

/* Pricing Page */
.pricing-controls {
  display: flex;
  justify-content: center;
  align-items: center;
  gap: 24px;
  margin-bottom: 48px;
}

.billing-toggle {
  display: flex;
  background: var(--gray-200);
  border-radius: 30px;
  padding: 4px;
}

.billing-toggle button {
  padding: 10px 24px;
  border-radius: 26px;
  font-weight: 600;
  color: var(--gray-600);
  transition: var(--transition);
}

.billing-toggle button.active {
  background: var(--white);
  color: var(--primary);
  box-shadow: var(--shadow-sm);
}

.save-badge {
  background: var(--accent);
  color: var(--white);
  padding: 6px 12px;
  border-radius: 20px;
  font-size: 0.75rem;
  font-weight: 700;
}

.team-size-slider {
  display: flex;
  align-items: center;
  gap: 16px;
  justify-content: center;
}

.team-size-slider input[type="range"] {
  width: 200px;
  accent-color: var(--primary);
}

.pricing-cards {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 24px;
  margin-bottom: 60px;
}

.pricing-card {
  background: var(--white);
  border-radius: var(--radius-lg);
  padding: 32px;
  border: 2px solid var(--gray-200);
  position: relative;
}

.pricing-card.popular {
  border-color: var(--primary);
  transform: scale(1.02);
}

.pricing-card.popular::before {
  content: 'MOST POPULAR';
  position: absolute;
  top: -12px;
  left: 50%;
  transform: translateX(-50%);
  background: var(--primary);
  color: var(--white);
  padding: 4px 16px;
  border-radius: 20px;
  font-size: 0.75rem;
  font-weight: 700;
}

.pricing-card h3 {
  font-size: 1.25rem;
  margin-bottom: 8px;
}

.pricing-card .price {
  font-size: 2.5rem;
  font-weight: 800;
  color: var(--primary);
  margin-bottom: 24px;
}

.pricing-card .price span {
  font-size: 1rem;
  font-weight: 500;
  color: var(--gray-500);
}

.pricing-card ul {
  list-style: none;
  margin-bottom: 24px;
}

.pricing-card ul li {
  padding: 8px 0;
  font-size: 0.875rem;
  color: var(--gray-700);
  display: flex;
  align-items: center;
  gap: 8px;
}

.pricing-card ul li::before {
  content: '✓';
  color: var(--primary);
  font-weight: 700;
}

.comparison-table {
  width: 100%;
  border-collapse: collapse;
  background: var(--white);
  border-radius: var(--radius-lg);
  overflow: hidden;
  margin-bottom: 60px;
}

.comparison-table th,
.comparison-table td {
  padding: 16px 20px;
  text-align: left;
  border-bottom: 1px solid var(--gray-200);
}

.comparison-table th {
  background: var(--gray-100);
  font-weight: 600;
  color: var(--gray-700);
}

.comparison-table td {
  font-size: 0.875rem;
}

.comparison-table tr:hover td {
  background: var(--gray-100);
}

.comparison-expand {
  text-align: center;
  padding: 16px;
}

/* FAQ Accordion */
.faq-list {
  max-width: 800px;
  margin: 0 auto;
}

.faq-item {
  border-bottom: 1px solid var(--gray-200);
}

.faq-question {
  width: 100%;
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding: 24px 0;
  font-size: 1.125rem;
  font-weight: 600;
  text-align: left;
}

.faq-question svg {
  width: 24px;
  height: 24px;
  transition: transform 0.3s;
}

.faq-item.active .faq-question svg {
  transform: rotate(180deg);
}

.faq-answer {
  max-height: 0;
  overflow: hidden;
  transition: max-height 0.3s ease;
}

.faq-item.active .faq-answer {
  max-height: 500px;
  padding-bottom: 24px;
}

.faq-answer p {
  color: var(--gray-600);
  line-height: 1.7;
}

/* Login/Signup */
.auth-page {
  min-height: 100vh;
  display: flex;
  flex-direction: column;
}

.auth-container {
  flex: 1;
  display: grid;
  grid-template-columns: 1fr 1fr;
}

.auth-form-section {
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 48px;
}

.auth-form {
  width: 100%;
  max-width: 400px;
}

.auth-form h1 {
  font-size: 2rem;
  margin-bottom: 8px;
}

.auth-form > p {
  color: var(--gray-600);
  margin-bottom: 32px;
}

.social-auth {
  display: flex;
  flex-direction: column;
  gap: 12px;
  margin-bottom: 24px;
}

.social-btn {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 12px;
  padding: 14px;
  border: 1px solid var(--gray-300);
  border-radius: var(--radius-md);
  font-weight: 500;
  transition: var(--transition);
}

.social-btn:hover {
  border-color: var(--primary);
  background: var(--gray-100);
}

.social-btn svg {
  width: 20px;
  height: 20px;
}

.auth-divider {
  display: flex;
  align-items: center;
  gap: 16px;
  margin: 24px 0;
  color: var(--gray-500);
  font-size: 0.875rem;
}

.auth-divider::before,
.auth-divider::after {
  content: '';
  flex: 1;
  height: 1px;
  background: var(--gray-300);
}

.auth-input {
  width: 100%;
  padding: 14px 16px;
  border: 1px solid var(--gray-300);
  border-radius: var(--radius-md);
  font-size: 1rem;
  transition: var(--transition);
  margin-bottom: 16px;
}

.auth-input:focus {
  outline: none;
  border-color: var(--primary);
  box-shadow: 0 0 0 3px rgba(24, 104, 219, 0.1);
}

.auth-footer {
  margin-top: 24px;
  font-size: 0.875rem;
  color: var(--gray-600);
  text-align: center;
}

.auth-footer a {
  color: var(--primary);
  font-weight: 500;
}

.auth-sidebar {
  background: var(--gradient-primary);
  color: var(--white);
  padding: 48px;
  display: flex;
  flex-direction: column;
  justify-content: center;
}

.auth-sidebar blockquote {
  font-size: 1.5rem;
  line-height: 1.5;
  margin-bottom: 32px;
}

.auth-sidebar cite {
  font-style: normal;
}

.auth-sidebar cite strong {
  display: block;
  margin-top: 16px;
}

/* Cookie Banner */
.cookie-banner {
  position: fixed;
  bottom: 24px;
  left: 24px;
  right: 24px;
  background: var(--white);
  border-radius: var(--radius-lg);
  padding: 24px;
  box-shadow: var(--shadow-xl);
  z-index: 1001;
  max-width: 500px;
}

.cookie-banner h4 {
  margin-bottom: 8px;
}

.cookie-banner p {
  font-size: 0.875rem;
  color: var(--gray-600);
  margin-bottom: 16px;
}

.cookie-actions {
  display: flex;
  gap: 12px;
}

.cookie-banner .btn-sm {
  padding: 8px 16px;
}

/* Cookie Modal */
.modal-overlay {
  position: fixed;
  inset: 0;
  background: rgba(0,0,0,0.5);
  z-index: 1002;
  display: none;
  align-items: center;
  justify-content: center;
}

.modal-overlay.active {
  display: flex;
}

.modal {
  background: var(--white);
  border-radius: var(--radius-lg);
  padding: 32px;
  max-width: 500px;
  width: 90%;
  max-height: 80vh;
  overflow-y: auto;
}

.modal h3 {
  margin-bottom: 24px;
}

.cookie-category {
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding: 16px 0;
  border-bottom: 1px solid var(--gray-200);
}

.cookie-category h5 {
  font-size: 0.875rem;
}

.cookie-category p {
  font-size: 0.75rem;
  color: var(--gray-500);
  margin-top: 4px;
}

.toggle-switch {
  width: 48px;
  height: 24px;
  background: var(--gray-300);
  border-radius: 12px;
  position: relative;
  cursor: pointer;
  transition: var(--transition);
}

.toggle-switch.active {
  background: var(--primary);
}

.toggle-switch::after {
  content: '';
  position: absolute;
  width: 20px;
  height: 20px;
  background: var(--white);
  border-radius: 50%;
  top: 2px;
  left: 2px;
  transition: var(--transition);
}

.toggle-switch.active::after {
  left: 26px;
}

/* Responsive */
@media (max-width: 1024px) {
  .container {
    padding: 0 20px;
  }

  .nav-links {
    display: none;
  }

  .feature-highlight,
  .screen-recorder {
    grid-template-columns: 1fr;
  }

  .video-editor-grid,
  .integrations-grid {
    grid-template-columns: repeat(3, 1fr);
  }

  .security-grid,
  .use-cases-grid {
    grid-template-columns: repeat(2, 1fr);
  }

  .features-grid {
    grid-template-columns: repeat(2, 1fr);
  }

  .testimonials-grid,
  .pricing-cards {
    grid-template-columns: repeat(2, 1fr);
  }

  .footer-grid {
    grid-template-columns: repeat(2, 1fr);
  }

  .auth-container {
    grid-template-columns: 1fr;
  }

  .auth-sidebar {
    display: none;
  }
}

@media (max-width: 768px) {
  .section {
    padding: 60px 0;
  }

  h1 { font-size: 2rem; }
  h2 { font-size: 1.75rem; }

  .video-editor-grid,
  .integrations-grid,
  .features-grid,
  .testimonials-grid,
  .pricing-cards {
    grid-template-columns: 1fr;
  }

  .security-grid,
  .use-cases-grid,
  .enterprise-stats {
    grid-template-columns: 1fr;
  }

  .footer-grid {
    grid-template-columns: 1fr;
  }

  .footer-bottom {
    flex-direction: column;
    gap: 16px;
    text-align: center;
  }

  .pricing-controls {
    flex-direction: column;
  }
}

/* ClipCast Design System */
@import url('https://fonts.googleapis.com/css2?family=Inter:wght@400;500;600;700;800&display=swap');

:root {
  --primary: #1868DB;
  --primary-dark: #1351a8;
  --primary-light: #e8f0fd;
  --accent: #FF613D;
  --accent-dark: #e5501f;
  --dark: #292A2E;
  --gray-900: #1a1a1f;
  --gray-800: #2d2d35;
  --gray-700: #45454f;
  --gray-600: #636370;
  --gray-500: #8d8d9a;
  --gray-400: #b5b5c0;
  --gray-300: #d8d8e0;
  --gray-200: #eeeff1;
  --gray-100: #f5f5f7;
  --white: #ffffff;
  --gradient-primary: linear-gradient(135deg, var(--primary) 0%, #7c3aed 100%);
  --gradient-accent: linear-gradient(135deg, var(--accent) 0%, #ff8f6b 100%);
  --gradient-bg: linear-gradient(180deg, #f8faff 0%, #ffffff 100%);
  --shadow-sm: 0 1px 2px rgba(0,0,0,0.05);
  --shadow-md: 0 4px 12px rgba(0,0,0,0.08);
  --shadow-lg: 0 8px 30px rgba(0,0,0,0.12);
  --shadow-xl: 0 20px 50px rgba(0,0,0,0.15);
  --radius-sm: 8px;
  --radius-md: 12px;
  --radius-lg: 16px;
  --radius-xl: 24px;
  --transition: all 0.3s ease;
}

*, *::before, *::after {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

html {
  scroll-behavior: smooth;
}

body {
  font-family: 'Inter', -apple-system, BlinkMacSystemFont, sans-serif;
  font-size: 16px;
  line-height: 1.6;
  color: var(--dark);
  background: var(--white);
  -webkit-font-smoothing: antialiased;
}

img {
  max-width: 100%;
  display: block;
}

a {
  color: inherit;
  text-decoration: none;
}

button {
  font-family: inherit;
  cursor: pointer;
  border: none;
  background: none;
}

.container {
  max-width: 1200px;
  margin: 0 auto;
  padding: 0 24px;
}

/* Typography */
h1, h2, h3, h4, h5, h6 {
  font-weight: 700;
  line-height: 1.2;
}

h1 { font-size: clamp(2.5rem, 5vw, 4rem); }
h2 { font-size: clamp(2rem, 4vw, 3rem); }
h3 { font-size: clamp(1.5rem, 3vw, 2rem); }
h4 { font-size: 1.25rem; }

.text-gradient {
  background: var(--gradient-primary);
  -webkit-background-clip: text;
  -webkit-text-fill-color: transparent;
  background-clip: text;
}

/* Buttons */
.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  padding: 14px 28px;
  font-size: 1rem;
  font-weight: 600;
  border-radius: var(--radius-md);
  transition: var(--transition);
  white-space: nowrap;
}

.btn-primary {
  background: var(--primary);
  color: var(--white);
}

.btn-primary:hover {
  background: var(--primary-dark);
  transform: translateY(-2px);
  box-shadow: var(--shadow-md);
}

.btn-accent {
  background: var(--accent);
  color: var(--white);
}

.btn-accent:hover {
  background: var(--accent-dark);
  transform: translateY(-2px);
  box-shadow: var(--shadow-md);
}

.btn-outline {
  background: transparent;
  border: 2px solid var(--gray-300);
  color: var(--dark);
}

.btn-outline:hover {
  border-color: var(--primary);
  color: var(--primary);
}

.btn-lg {
  padding: 18px 36px;
  font-size: 1.125rem;
}

.btn-sm {
  padding: 10px 20px;
  font-size: 0.875rem;
}

/* Nav */
.navbar {
  position: fixed;
  top: 0;
  left: 0;
  right: 0;
  background: rgba(255,255,255,0.95);
  backdrop-filter: blur(10px);
  z-index: 1000;
  border-bottom: 1px solid var(--gray-200);
}

.navbar .container {
  display: flex;
  align-items: center;
  justify-content: space-between;
  height: 72px;
}

.nav-logo {
  font-size: 1.5rem;
  font-weight: 800;
  color: var(--primary);
  display: flex;
  align-items: center;
  gap: 8px;
}

.nav-logo svg {
  width: 32px;
  height: 32px;
}

.nav-links {
  display: flex;
  align-items: center;
  gap: 32px;
  list-style: none;
}

.nav-links a {
  font-weight: 500;
  color: var(--gray-700);
  transition: var(--transition);
}

.nav-links a:hover {
  color: var(--primary);
}

.nav-actions {
  display: flex;
  align-items: center;
  gap: 16px;
}

/* Sections */
.section {
  padding: 100px 0;
}

.section-sm {
  padding: 60px 0;
}

.section-alt {
  background: var(--gray-100);
}

.section-dark {
  background: var(--gray-900);
  color: var(--white);
}

.section-header {
  text-align: center;
  max-width: 700px;
  margin: 0 auto 60px;
}

.section-header h2 {
  margin-bottom: 16px;
}

.section-header p {
  font-size: 1.125rem;
  color: var(--gray-600);
}

/* Cards */
.card {
  background: var(--white);
  border-radius: var(--radius-lg);
  padding: 32px;
  box-shadow: var(--shadow-md);
  transition: var(--transition);
}

.card:hover {
  transform: translateY(-4px);
  box-shadow: var(--shadow-lg);
}

/* Logo Bar */
.logo-bar {
  padding: 40px 0;
  background: var(--gray-100);
  text-align: center;
}

.logo-bar p {
  font-size: 0.875rem;
  color: var(--gray-500);
  margin-bottom: 24px;
  text-transform: uppercase;
  letter-spacing: 1px;
}

.logo-bar-logos {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 48px;
  flex-wrap: wrap;
}

.logo-bar-logos span {
  font-size: 1.25rem;
  font-weight: 700;
  color: var(--gray-400);
}

/* Hero */
.hero {
  padding: 160px 0 100px;
  background: var(--gradient-bg);
  text-align: center;
}

.hero h1 {
  margin-bottom: 24px;
}

.hero-subtitle {
  font-size: 1.25rem;
  color: var(--gray-600);
  max-width: 600px;
  margin: 0 auto 40px;
}

.hero-actions {
  display: flex;
  gap: 16px;
  justify-content: center;
  flex-wrap: wrap;
}

.hero-stats {
  margin-top: 60px;
  font-size: 0.875rem;
  color: var(--gray-500);
}

/* Feature Highlight */
.feature-highlight {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 60px;
  align-items: center;
}

.feature-highlight-content h2 {
  margin-bottom: 16px;
}

.feature-highlight-content p {
  color: var(--gray-600);
  margin-bottom: 24px;
}

.feature-badge {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  background: var(--accent);
  color: var(--white);
  padding: 6px 12px;
  border-radius: 20px;
  font-size: 0.75rem;
  font-weight: 600;
  text-transform: uppercase;
  margin-bottom: 16px;
}

.feature-image {
  background: var(--primary-light);
  border-radius: var(--radius-xl);
  padding: 40px;
  display: flex;
  align-items: center;
  justify-content: center;
}

/* Screen Recorder */
.screen-recorder {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 60px;
  align-items: center;
}

/* Video Editor */
.video-editor-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 24px;
  margin-top: 48px;
}

.video-editor-item {
  background: var(--white);
  border-radius: var(--radius-lg);
  padding: 24px;
  box-shadow: var(--shadow-sm);
  border: 1px solid var(--gray-200);
}

.video-editor-item h4 {
  margin-bottom: 8px;
}

.video-editor-item p {
  font-size: 0.875rem;
  color: var(--gray-600);
}

/* Integrations */
.integrations-grid {
  display: grid;
  grid-template-columns: repeat(6, 1fr);
  gap: 32px;
  margin-top: 48px;
}

.integration-item {
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 20px;
  background: var(--white);
  border-radius: var(--radius-md);
  border: 1px solid var(--gray-200);
  transition: var(--transition);
}

.integration-item:hover {
  border-color: var(--primary);
  transform: translateY(-2px);
}

/* Security */
.security-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 24px;
  margin-top: 48px;
}

.security-item {
  text-align: center;
  padding: 32px 24px;
  background: var(--white);
  border-radius: var(--radius-lg);
  border: 1px solid var(--gray-200);
}

.security-item h4 {
  margin-top: 16px;
}

/* Use Cases */
.use-cases-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 24px;
  margin-top: 48px;
}

.use-case-item {
  padding: 32px;
  background: var(--white);
  border-radius: var(--radius-lg);
  text-align: center;
  transition: var(--transition);
  border: 1px solid var(--gray-200);
}

.use-case-item:hover {
  border-color: var(--primary);
  transform: translateY(-4px);
}

.use-case-icon {
  width: 56px;
  height: 56px;
  background: var(--primary-light);
  border-radius: var(--radius-md);
  display: flex;
  align-items: center;
  justify-content: center;
  margin: 0 auto 16px;
}

/* Features Grid */
.features-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 24px;
  margin-top: 48px;
}

.feature-item {
  display: flex;
  gap: 16px;
  padding: 24px;
  background: var(--white);
  border-radius: var(--radius-md);
  border: 1px solid var(--gray-200);
}

.feature-icon {
  width: 44px;
  height: 44px;
  background: var(--primary);
  border-radius: var(--radius-sm);
  display: flex;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
}

.feature-icon svg {
  width: 22px;
  height: 22px;
  stroke: var(--white);
}

/* Testimonials */
.testimonials-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 24px;
  margin-top: 48px;
}

.testimonial-card {
  background: var(--white);
  border-radius: var(--radius-lg);
  padding: 32px;
  border: 1px solid var(--gray-200);
}

.testimonial-card p {
  font-size: 1rem;
  line-height: 1.7;
  margin-bottom: 24px;
  color: var(--gray-700);
}

.testimonial-author {
  display: flex;
  align-items: center;
  gap: 12px;
}

.testimonial-avatar {
  width: 48px;
  height: 48px;
  background: var(--gradient-primary);
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
  color: var(--white);
  font-weight: 700;
}

.testimonial-info h5 {
  font-weight: 600;
}

.testimonial-info p {
  font-size: 0.875rem;
  color: var(--gray-500);
  margin-bottom: 0;
}

/* Blog */
.blog-grid {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: 32px;
  margin-top: 48px;
}

.blog-card {
  background: var(--white);
  border-radius: var(--radius-lg);
  overflow: hidden;
  border: 1px solid var(--gray-200);
  transition: var(--transition);
}

.blog-card:hover {
  transform: translateY(-4px);
  box-shadow: var(--shadow-lg);
}

.blog-card-content {
  padding: 24px;
}

.blog-card-label {
  font-size: 0.75rem;
  font-weight: 600;
  color: var(--primary);
  text-transform: uppercase;
  margin-bottom: 8px;
}

.blog-card h4 {
  margin-bottom: 8px;
}

.blog-card p {
  font-size: 0.875rem;
  color: var(--gray-600);
}

/* CTA Banner */
.cta-banner {
  background: var(--gradient-primary);
  color: var(--white);
  text-align: center;
  padding: 80px 24px;
  border-radius: var(--radius-xl);
  margin: 0 24px;
}

.cta-banner h2 {
  margin-bottom: 16px;
}

.cta-banner p {
  font-size: 1.125rem;
  opacity: 0.9;
  margin-bottom: 32px;
}

.cta-banner .btn {
  background: var(--white);
  color: var(--primary);
}

.cta-banner .btn:hover {
  background: var(--gray-100);
}

/* Footer */
.footer {
  background: var(--gray-900);
  color: var(--gray-400);
  padding: 80px 0 40px;
}

.footer-grid {
  display: grid;
  grid-template-columns: 2fr repeat(4, 1fr);
  gap: 48px;
  margin-bottom: 48px;
}

.footer-brand p {
  margin-top: 16px;
  font-size: 0.875rem;
}

.footer h5 {
  color: var(--white);
  margin-bottom: 20px;
  font-size: 0.875rem;
  text-transform: uppercase;
  letter-spacing: 1px;
}

.footer ul {
  list-style: none;
}

.footer ul li {
  margin-bottom: 12px;
}

.footer ul li a:hover {
  color: var(--white);
}

.footer-bottom {
  padding-top: 40px;
  border-top: 1px solid var(--gray-800);
  display: flex;
  justify-content: space-between;
  align-items: center;
  font-size: 0.875rem;
}

.footer-legal {
  display: flex;
  gap: 24px;
}

/* Enterprise Page */
.enterprise-stats {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 32px;
  margin-top: 48px;
}

.enterprise-stat {
  text-align: center;
  padding: 32px;
  background: var(--white);
  border-radius: var(--radius-lg);
  border: 1px solid var(--gray-200);
}

.enterprise-stat h2 {
  font-size: 3rem;
  color: var(--primary);
  margin-bottom: 8px;
}

.enterprise-stat p {
  color: var(--gray-600);
}

/* Pricing Page */
.pricing-controls {
  display: flex;
  justify-content: center;
  align-items: center;
  gap: 24px;
  margin-bottom: 48px;
}

.billing-toggle {
  display: flex;
  background: var(--gray-200);
  border-radius: 30px;
  padding: 4px;
}

.billing-toggle button {
  padding: 10px 24px;
  border-radius: 26px;
  font-weight: 600;
  color: var(--gray-600);
  transition: var(--transition);
}

.billing-toggle button.active {
  background: var(--white);
  color: var(--primary);
  box-shadow: var(--shadow-sm);
}

.save-badge {
  background: var(--accent);
  color: var(--white);
  padding: 6px 12px;
  border-radius: 20px;
  font-size: 0.75rem;
  font-weight: 700;
}

.team-size-slider {
  display: flex;
  align-items: center;
  gap: 16px;
  justify-content: center;
}

.team-size-slider input[type="range"] {
  width: 200px;
  accent-color: var(--primary);
}

.pricing-cards {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 24px;
  margin-bottom: 60px;
}

.pricing-card {
  background: var(--white);
  border-radius: var(--radius-lg);
  padding: 32px;
  border: 2px solid var(--gray-200);
  position: relative;
}

.pricing-card.popular {
  border-color: var(--primary);
  transform: scale(1.02);
}

.pricing-card.popular::before {
  content: 'MOST POPULAR';
  position: absolute;
  top: -12px;
  left: 50%;
  transform: translateX(-50%);
  background: var(--primary);
  color: var(--white);
  padding: 4px 16px;
  border-radius: 20px;
  font-size: 0.75rem;
  font-weight: 700;
}

.pricing-card h3 {
  font-size: 1.25rem;
  margin-bottom: 8px;
}

.pricing-card .price {
  font-size: 2.5rem;
  font-weight: 800;
  color: var(--primary);
  margin-bottom: 24px;
}

.pricing-card .price span {
  font-size: 1rem;
  font-weight: 500;
  color: var(--gray-500);
}

.pricing-card ul {
  list-style: none;
  margin-bottom: 24px;
}

.pricing-card ul li {
  padding: 8px 0;
  font-size: 0.875rem;
  color: var(--gray-700);
  display: flex;
  align-items: center;
  gap: 8px;
}

.pricing-card ul li::before {
  content: '✓';
  color: var(--primary);
  font-weight: 700;
}

.comparison-table {
  width: 100%;
  border-collapse: collapse;
  background: var(--white);
  border-radius: var(--radius-lg);
  overflow: hidden;
  margin-bottom: 60px;
}

.comparison-table th,
.comparison-table td {
  padding: 16px 20px;
  text-align: left;
  border-bottom: 1px solid var(--gray-200);
}

.comparison-table th {
  background: var(--gray-100);
  font-weight: 600;
  color: var(--gray-700);
}

.comparison-table td {
  font-size: 0.875rem;
}

.comparison-table tr:hover td {
  background: var(--gray-100);
}

.comparison-expand {
  text-align: center;
  padding: 16px;
}

/* FAQ Accordion */
.faq-list {
  max-width: 800px;
  margin: 0 auto;
}

.faq-item {
  border-bottom: 1px solid var(--gray-200);
}

.faq-question {
  width: 100%;
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding: 24px 0;
  font-size: 1.125rem;
  font-weight: 600;
  text-align: left;
}

.faq-question svg {
  width: 24px;
  height: 24px;
  transition: transform 0.3s;
}

.faq-item.active .faq-question svg {
  transform: rotate(180deg);
}

.faq-answer {
  max-height: 0;
  overflow: hidden;
  transition: max-height 0.3s ease;
}

.faq-item.active .faq-answer {
  max-height: 500px;
  padding-bottom: 24px;
}

.faq-answer p {
  color: var(--gray-600);
  line-height: 1.7;
}

/* Login/Signup */
.auth-page {
  min-height: 100vh;
  display: flex;
  flex-direction: column;
}

.auth-container {
  flex: 1;
  display: grid;
  grid-template-columns: 1fr 1fr;
}

.auth-form-section {
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 48px;
}

.auth-form {
  width: 100%;
  max-width: 400px;
}

.auth-form h1 {
  font-size: 2rem;
  margin-bottom: 8px;
}

.auth-form > p {
  color: var(--gray-600);
  margin-bottom: 32px;
}

.social-auth {
  display: flex;
  flex-direction: column;
  gap: 12px;
  margin-bottom: 24px;
}

.social-btn {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 12px;
  padding: 14px;
  border: 1px solid var(--gray-300);
  border-radius: var(--radius-md);
  font-weight: 500;
  transition: var(--transition);
}

.social-btn:hover {
  border-color: var(--primary);
  background: var(--gray-100);
}

.social-btn svg {
  width: 20px;
  height: 20px;
}

.auth-divider {
  display: flex;
  align-items: center;
  gap: 16px;
  margin: 24px 0;
  color: var(--gray-500);
  font-size: 0.875rem;
}

.auth-divider::before,
.auth-divider::after {
  content: '';
  flex: 1;
  height: 1px;
  background: var(--gray-300);
}

.auth-input {
  width: 100%;
  padding: 14px 16px;
  border: 1px solid var(--gray-300);
  border-radius: var(--radius-md);
  font-size: 1rem;
  transition: var(--transition);
  margin-bottom: 16px;
}

.auth-input:focus {
  outline: none;
  border-color: var(--primary);
  box-shadow: 0 0 0 3px rgba(24, 104, 219, 0.1);
}

.auth-footer {
  margin-top: 24px;
  font-size: 0.875rem;
  color: var(--gray-600);
  text-align: center;
}

.auth-footer a {
  color: var(--primary);
  font-weight: 500;
}

.auth-sidebar {
  background: var(--gradient-primary);
  color: var(--white);
  padding: 48px;
  display: flex;
  flex-direction: column;
  justify-content: center;
}

.auth-sidebar blockquote {
  font-size: 1.5rem;
  line-height: 1.5;
  margin-bottom: 32px;
}

.auth-sidebar cite {
  font-style: normal;
}

.auth-sidebar cite strong {
  display: block;
  margin-top: 16px;
}

/* Cookie Banner */
.cookie-banner {
  position: fixed;
  bottom: 24px;
  left: 24px;
  right: 24px;
  background: var(--white);
  border-radius: var(--radius-lg);
  padding: 24px;
  box-shadow: var(--shadow-xl);
  z-index: 1001;
  max-width: 500px;
}

.cookie-banner h4 {
  margin-bottom: 8px;
}

.cookie-banner p {
  font-size: 0.875rem;
  color: var(--gray-600);
  margin-bottom: 16px;
}

.cookie-actions {
  display: flex;
  gap: 12px;
}

.cookie-banner .btn-sm {
  padding: 8px 16px;
}

/* Cookie Modal */
.modal-overlay {
  position: fixed;
  inset: 0;
  background: rgba(0,0,0,0.5);
  z-index: 1002;
  display: none;
  align-items: center;
  justify-content: center;
}

.modal-overlay.active {
  display: flex;
}

.modal {
  background: var(--white);
  border-radius: var(--radius-lg);
  padding: 32px;
  max-width: 500px;
  width: 90%;
  max-height: 80vh;
  overflow-y: auto;
}

.modal h3 {
  margin-bottom: 24px;
}

.cookie-category {
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding: 16px 0;
  border-bottom: 1px solid var(--gray-200);
}

.cookie-category h5 {
  font-size: 0.875rem;
}

.cookie-category p {
  font-size: 0.75rem;
  color: var(--gray-500);
  margin-top: 4px;
}

.toggle-switch {
  width: 48px;
  height: 24px;
  background: var(--gray-300);
  border-radius: 12px;
  position: relative;
  cursor: pointer;
  transition: var(--transition);
}

.toggle-switch.active {
  background: var(--primary);
}

.toggle-switch::after {
  content: '';
  position: absolute;
  width: 20px;
  height: 20px;
  background: var(--white);
  border-radius: 50%;
  top: 2px;
  left: 2px;
  transition: var(--transition);
}

.toggle-switch.active::after {
  left: 26px;
}

/* Responsive */
@media (max-width: 1024px) {
  .container {
    padding: 0 20px;
  }

  .nav-links {
    display: none;
  }

  .feature-highlight,
  .screen-recorder {
    grid-template-columns: 1fr;
  }

  .video-editor-grid,
  .integrations-grid {
    grid-template-columns: repeat(3, 1fr);
  }

  .security-grid,
  .use-cases-grid {
    grid-template-columns: repeat(2, 1fr);
  }

  .features-grid {
    grid-template-columns: repeat(2, 1fr);
  }

  .testimonials-grid,
  .pricing-cards {
    grid-template-columns: repeat(2, 1fr);
  }

  .footer-grid {
    grid-template-columns: repeat(2, 1fr);
  }

  .auth-container {
    grid-template-columns: 1fr;
  }

  .auth-sidebar {
    display: none;
  }
}

@media (max-width: 768px) {
  .section {
    padding: 60px 0;
  }

  h1 { font-size: 2rem; }
  h2 { font-size: 1.75rem; }

  .video-editor-grid,
  .integrations-grid,
  .features-grid,
  .testimonials-grid,
  .pricing-cards {
    grid-template-columns: 1fr;
  }

  .security-grid,
  .use-cases-grid,
  .enterprise-stats {
    grid-template-columns: 1fr;
  }

  .footer-grid {
    grid-template-columns: 1fr;
  }

  .footer-bottom {
    flex-direction: column;
    gap: 16px;
    text-align: center;
  }

  .pricing-controls {
    flex-direction: column;
  }
}

raw_arguments.content:
/* ClipCast Design System */
@import url('https://fonts.googleapis.com/css2?family=Inter:wght@400;500;600;700;800&display=swap');

:root {
  --primary: #1868DB;
  --primary-dark: #1351a8;
  --primary-light: #e8f0fd;
  --accent: #FF613D;
  --accent-dark: #e5501f;
  --dark: #292A2E;
  --gray-900: #1a1a1f;
  --gray-800: #2d2d35;
  --gray-700: #45454f;
  --gray-600: #636370;
  --gray-500: #8d8d9a;
  --gray-400: #b5b5c0;
  --gray-300: #d8d8e0;
  --gray-200: #eeeff1;
  --gray-100: #f5f5f7;
  --white: #ffffff;
  --gradient-primary: linear-gradient(135deg, var(--primary) 0%, #7c3aed 100%);
  --gradient-accent: linear-gradient(135deg, var(--accent) 0%, #ff8f6b 100%);
  --gradient-bg: linear-gradient(180deg, #f8faff 0%, #ffffff 100%);
  --shadow-sm: 0 1px 2px rgba(0,0,0,0.05);
  --shadow-md: 0 4px 12px rgba(0,0,0,0.08);
  --shadow-lg: 0 8px 30px rgba(0,0,0,0.12);
  --shadow-xl: 0 20px 50px rgba(0,0,0,0.15);
  --radius-sm: 8px;
  --radius-md: 12px;
  --radius-lg: 16px;
  --radius-xl: 24px;
  --transition: all 0.3s ease;
}

*, *::before, *::after {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

html {
  scroll-behavior: smooth;
}

body {
  font-family: 'Inter', -apple-system, BlinkMacSystemFont, sans-serif;
  font-size: 16px;
  line-height: 1.6;
  color: var(--dark);
  background: var(--white);
  -webkit-font-smoothing: antialiased;
}

img {
  max-width: 100%;
  display: block;
}

a {
  color: inherit;
  text-decoration: none;
}

button {
  font-family: inherit;
  cursor: pointer;
  border: none;
  background: none;
}

.container {
  max-width: 1200px;
  margin: 0 auto;
  padding: 0 24px;
}

/* Typography */
h1, h2, h3, h4, h5, h6 {
  font-weight: 700;
  line-height: 1.2;
}

h1 { font-size: clamp(2.5rem, 5vw, 4rem); }
h2 { font-size: clamp(2rem, 4vw, 3rem); }
h3 { font-size: clamp(1.5rem, 3vw, 2rem); }
h4 { font-size: 1.25rem; }

.text-gradient {
  background: var(--gradient-primary);
  -webkit-background-clip: text;
  -webkit-text-fill-color: transparent;
  background-clip: text;
}

/* Buttons */
.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  padding: 14px 28px;
  font-size: 1rem;
  font-weight: 600;
  border-radius: var(--radius-md);
  transition: var(--transition);
  white-space: nowrap;
}

.btn-primary {
  background: var(--primary);
  color: var(--white);
}

.btn-primary:hover {
  background: var(--primary-dark);
  transform: translateY(-2px);
  box-shadow: var(--shadow-md);
}

.btn-accent {
  background: var(--accent);
  color: var(--white);
}

.btn-accent:hover {
  background: var(--accent-dark);
  transform: translateY(-2px);
  box-shadow: var(--shadow-md);
}

.btn-outline {
  background: transparent;
  border: 2px solid var(--gray-300);
  color: var(--dark);
}

.btn-outline:hover {
  border-color: var(--primary);
  color: var(--primary);
}

.btn-lg {
  padding: 18px 36px;
  font-size: 1.125rem;
}

.btn-sm {
  padding: 10px 20px;
  font-size: 0.875rem;
}

/* Nav */
.navbar {
  position: fixed;
  top: 0;
  left: 0;
  right: 0;
  background: rgba(255,255,255,0.95);
  backdrop-filter: blur(10px);
  z-index: 1000;
  border-bottom: 1px solid var(--gray-200);
}

.navbar .container {
  display: flex;
  align-items: center;
  justify-content: space-between;
  height: 72px;
}

.nav-logo {
  font-size: 1.5rem;
  font-weight: 800;
  color: var(--primary);
  display: flex;
  align-items: center;
  gap: 8px;
}

.nav-logo svg {
  width: 32px;
  height: 32px;
}

.nav-links {
  display: flex;
  align-items: center;
  gap: 32px;
  list-style: none;
}

.nav-links a {
  font-weight: 500;
  color: var(--gray-700);
  transition: var(--transition);
}

.nav-links a:hover {
  color: var(--primary);
}

.nav-actions {
  display: flex;
  align-items: center;
  gap: 16px;
}

/* Sections */
.section {
  padding: 100px 0;
}

.section-sm {
  padding: 60px 0;
}

.section-alt {
  background: var(--gray-100);
}

.section-dark {
  background: var(--gray-900);
  color: var(--white);
}

.section-header {
  text-align: center;
  max-width: 700px;
  margin: 0 auto 60px;
}

.section-header h2 {
  margin-bottom: 16px;
}

.section-header p {
  font-size: 1.125rem;
  color: var(--gray-600);
}

/* Cards */
.card {
  background: var(--white);
  border-radius: var(--radius-lg);
  padding: 32px;
  box-shadow: var(--shadow-md);
  transition: var(--transition);
}

.card:hover {
  transform: translateY(-4px);
  box-shadow: var(--shadow-lg);
}

/* Logo Bar */
.logo-bar {
  padding: 40px 0;
  background: var(--gray-100);
  text-align: center;
}

.logo-bar p {
  font-size: 0.875rem;
  color: var(--gray-500);
  margin-bottom: 24px;
  text-transform: uppercase;
  letter-spacing: 1px;
}

.logo-bar-logos {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 48px;
  flex-wrap: wrap;
}

.logo-bar-logos span {
  font-size: 1.25rem;
  font-weight: 700;
  color: var(--gray-400);
}

/* Hero */
.hero {
  padding: 160px 0 100px;
  background: var(--gradient-bg);
  text-align: center;
}

.hero h1 {
  margin-bottom: 24px;
}

.hero-subtitle {
  font-size: 1.25rem;
  color: var(--gray-600);
  max-width: 600px;
  margin: 0 auto 40px;
}

.hero-actions {
  display: flex;
  gap: 16px;
  justify-content: center;
  flex-wrap: wrap;
}

.hero-stats {
  margin-top: 60px;
  font-size: 0.875rem;
  color: var(--gray-500);
}

/* Feature Highlight */
.feature-highlight {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 60px;
  align-items: center;
}

.feature-highlight-content h2 {
  margin-bottom: 16px;
}

.feature-highlight-content p {
  color: var(--gray-600);
  margin-bottom: 24px;
}

.feature-badge {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  background: var(--accent);
  color: var(--white);
  padding: 6px 12px;
  border-radius: 20px;
  font-size: 0.75rem;
  font-weight: 600;
  text-transform: uppercase;
  margin-bottom: 16px;
}

.feature-image {
  background: var(--primary-light);
  border-radius: var(--radius-xl);
  padding: 40px;
  display: flex;
  align-items: center;
  justify-content: center;
}

/* Screen Recorder */
.screen-recorder {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 60px;
  align-items: center;
}

/* Video Editor */
.video-editor-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 24px;
  margin-top: 48px;
}

.video-editor-item {
  background: var(--white);
  border-radius: var(--radius-lg);
  padding: 24px;
  box-shadow: var(--shadow-sm);
  border: 1px solid var(--gray-200);
}

.video-editor-item h4 {
  margin-bottom: 8px;
}

.video-editor-item p {
  font-size: 0.875rem;
  color: var(--gray-600);
}

/* Integrations */
.integrations-grid {
  display: grid;
  grid-template-columns: repeat(6, 1fr);
  gap: 32px;
  margin-top: 48px;
}

.integration-item {
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 20px;
  background: var(--white);
  border-radius: var(--radius-md);
  border: 1px solid var(--gray-200);
  transition: var(--transition);
}

.integration-item:hover {
  border-color: var(--primary);
  transform: translateY(-2px);
}

/* Security */
.security-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 24px;
  margin-top: 48px;
}

.security-item {
  text-align: center;
  padding: 32px 24px;
  background: var(--white);
  border-radius: var(--radius-lg);
  border: 1px solid var(--gray-200);
}

.security-item h4 {
  margin-top: 16px;
}

/* Use Cases */
.use-cases-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 24px;
  margin-top: 48px;
}

.use-case-item {
  padding: 32px;
  background: var(--white);
  border-radius: var(--radius-lg);
  text-align: center;
  transition: var(--transition);
  border: 1px solid var(--gray-200);
}

.use-case-item:hover {
  border-color: var(--primary);
  transform: translateY(-4px);
}

.use-case-icon {
  width: 56px;
  height: 56px;
  background: var(--primary-light);
  border-radius: var(--radius-md);
  display: flex;
  align-items: center;
  justify-content: center;
  margin: 0 auto 16px;
}

/* Features Grid */
.features-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 24px;
  margin-top: 48px;
}

.feature-item {
  display: flex;
  gap: 16px;
  padding: 24px;
  background: var(--white);
  border-radius: var(--radius-md);
  border: 1px solid var(--gray-200);
}

.feature-icon {
  width: 44px;
  height: 44px;
  background: var(--primary);
  border-radius: var(--radius-sm);
  display: flex;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
}

.feature-icon svg {
  width: 22px;
  height: 22px;
  stroke: var(--white);
}

/* Testimonials */
.testimonials-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 24px;
  margin-top: 48px;
}

.testimonial-card {
  background: var(--white);
  border-radius: var(--radius-lg);
  padding: 32px;
  border: 1px solid var(--gray-200);
}

.testimonial-card p {
  font-size: 1rem;
  line-height: 1.7;
  margin-bottom: 24px;
  color: var(--gray-700);
}

.testimonial-author {
  display: flex;
  align-items: center;
  gap: 12px;
}

.testimonial-avatar {
  width: 48px;
  height: 48px;
  background: var(--gradient-primary);
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
  color: var(--white);
  font-weight: 700;
}

.testimonial-info h5 {
  font-weight: 600;
}

.testimonial-info p {
  font-size: 0.875rem;
  color: var(--gray-500);
  margin-bottom: 0;
}

/* Blog */
.blog-grid {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: 32px;
  margin-top: 48px;
}

.blog-card {
  background: var(--white);
  border-radius: var(--radius-lg);
  overflow: hidden;
  border: 1px solid var(--gray-200);
  transition: var(--transition);
}

.blog-card:hover {
  transform: translateY(-4px);
  box-shadow: var(--shadow-lg);
}

.blog-card-content {
  padding: 24px;
}

.blog-card-label {
  font-size: 0.75rem;
  font-weight: 600;
  color: var(--primary);
  text-transform: uppercase;
  margin-bottom: 8px;
}

.blog-card h4 {
  margin-bottom: 8px;
}

.blog-card p {
  font-size: 0.875rem;
  color: var(--gray-600);
}

/* CTA Banner */
.cta-banner {
  background: var(--gradient-primary);
  color: var(--white);
  text-align: center;
  padding: 80px 24px;
  border-radius: var(--radius-xl);
  margin: 0 24px;
}

.cta-banner h2 {
  margin-bottom: 16px;
}

.cta-banner p {
  font-size: 1.125rem;
  opacity: 0.9;
  margin-bottom: 32px;
}

.cta-banner .btn {
  background: var(--white);
  color: var(--primary);
}

.cta-banner .btn:hover {
  background: var(--gray-100);
}

/* Footer */
.footer {
  background: var(--gray-900);
  color: var(--gray-400);
  padding: 80px 0 40px;
}

.footer-grid {
  display: grid;
  grid-template-columns: 2fr repeat(4, 1fr);
  gap: 48px;
  margin-bottom: 48px;
}

.footer-brand p {
  margin-top: 16px;
  font-size: 0.875rem;
}

.footer h5 {
  color: var(--white);
  margin-bottom: 20px;
  font-size: 0.875rem;
  text-transform: uppercase;
  letter-spacing: 1px;
}

.footer ul {
  list-style: none;
}

.footer ul li {
  margin-bottom: 12px;
}

.footer ul li a:hover {
  color: var(--white);
}

.footer-bottom {
  padding-top: 40px;
  border-top: 1px solid var(--gray-800);
  display: flex;
  justify-content: space-between;
  align-items: center;
  font-size: 0.875rem;
}

.footer-legal {
  display: flex;
  gap: 24px;
}

/* Enterprise Page */
.enterprise-stats {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 32px;
  margin-top: 48px;
}

.enterprise-stat {
  text-align: center;
  padding: 32px;
  background: var(--white);
  border-radius: var(--radius-lg);
  border: 1px solid var(--gray-200);
}

.enterprise-stat h2 {
  font-size: 3rem;
  color: var(--primary);
  margin-bottom: 8px;
}

.enterprise-stat p {
  color: var(--gray-600);
}

/* Pricing Page */
.pricing-controls {
  display: flex;
  justify-content: center;
  align-items: center;
  gap: 24px;
  margin-bottom: 48px;
}

.billing-toggle {
  display: flex;
  background: var(--gray-200);
  border-radius: 30px;
  padding: 4px;
}

.billing-toggle button {
  padding: 10px 24px;
  border-radius: 26px;
  font-weight: 600;
  color: var(--gray-600);
  transition: var(--transition);
}

.billing-toggle button.active {
  background: var(--white);
  color: var(--primary);
  box-shadow: var(--shadow-sm);
}

.save-badge {
  background: var(--accent);
  color: var(--white);
  padding: 6px 12px;
  border-radius: 20px;
  font-size: 0.75rem;
  font-weight: 700;
}

.team-size-slider {
  display: flex;
  align-items: center;
  gap: 16px;
  justify-content: center;
}

.team-size-slider input[type="range"] {
  width: 200px;
  accent-color: var(--primary);
}

.pricing-cards {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 24px;
  margin-bottom: 60px;
}

.pricing-card {
  background: var(--white);
  border-radius: var(--radius-lg);
  padding: 32px;
  border: 2px solid var(--gray-200);
  position: relative;
}

.pricing-card.popular {
  border-color: var(--primary);
  transform: scale(1.02);
}

.pricing-card.popular::before {
  content: 'MOST POPULAR';
  position: absolute;
  top: -12px;
  left: 50%;
  transform: translateX(-50%);
  background: var(--primary);
  color: var(--white);
  padding: 4px 16px;
  border-radius: 20px;
  font-size: 0.75rem;
  font-weight: 700;
}

.pricing-card h3 {
  font-size: 1.25rem;
  margin-bottom: 8px;
}

.pricing-card .price {
  font-size: 2.5rem;
  font-weight: 800;
  color: var(--primary);
  margin-bottom: 24px;
}

.pricing-card .price span {
  font-size: 1rem;
  font-weight: 500;
  color: var(--gray-500);
}

.pricing-card ul {
  list-style: none;
  margin-bottom: 24px;
}

.pricing-card ul li {
  padding: 8px 0;
  font-size: 0.875rem;
  color: var(--gray-700);
  display: flex;
  align-items: center;
  gap: 8px;
}

.pricing-card ul li::before {
  content: '✓';
  color: var(--primary);
  font-weight: 700;
}

.comparison-table {
  width: 100%;
  border-collapse: collapse;
  background: var(--white);
  border-radius: var(--radius-lg);
  overflow: hidden;
  margin-bottom: 60px;
}

.comparison-table th,
.comparison-table td {
  padding: 16px 20px;
  text-align: left;
  border-bottom: 1px solid var(--gray-200);
}

.comparison-table th {
  background: var(--gray-100);
  font-weight: 600;
  color: var(--gray-700);
}

.comparison-table td {
  font-size: 0.875rem;
}

.comparison-table tr:hover td {
  background: var(--gray-100);
}

.comparison-expand {
  text-align: center;
  padding: 16px;
}

/* FAQ Accordion */
.faq-list {
  max-width: 800px;
  margin: 0 auto;
}

.faq-item {
  border-bottom: 1px solid var(--gray-200);
}

.faq-question {
  width: 100%;
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding: 24px 0;
  font-size: 1.125rem;
  font-weight: 600;
  text-align: left;
}

.faq-question svg {
  width: 24px;
  height: 24px;
  transition: transform 0.3s;
}

.faq-item.active .faq-question svg {
  transform: rotate(180deg);
}

.faq-answer {
  max-height: 0;
  overflow: hidden;
  transition: max-height 0.3s ease;
}

.faq-item.active .faq-answer {
  max-height: 500px;
  padding-bottom: 24px;
}

.faq-answer p {
  color: var(--gray-600);
  line-height: 1.7;
}

/* Login/Signup */
.auth-page {
  min-height: 100vh;
  display: flex;
  flex-direction: column;
}

.auth-container {
  flex: 1;
  display: grid;
  grid-template-columns: 1fr 1fr;
}

.auth-form-section {
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 48px;
}

.auth-form {
  width: 100%;
  max-width: 400px;
}

.auth-form h1 {
  font-size: 2rem;
  margin-bottom: 8px;
}

.auth-form > p {
  color: var(--gray-600);
  margin-bottom: 32px;
}

.social-auth {
  display: flex;
  flex-direction: column;
  gap: 12px;
  margin-bottom: 24px;
}

.social-btn {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 12px;
  padding: 14px;
  border: 1px solid var(--gray-300);
  border-radius: var(--radius-md);
  font-weight: 500;
  transition: var(--transition);
}

.social-btn:hover {
  border-color: var(--primary);
  background: var(--gray-100);
}

.social-btn svg {
  width: 20px;
  height: 20px;
}

.auth-divider {
  display: flex;
  align-items: center;
  gap: 16px;
  margin: 24px 0;
  color: var(--gray-500);
  font-size: 0.875rem;
}

.auth-divider::before,
.auth-divider::after {
  content: '';
  flex: 1;
  height: 1px;
  background: var(--gray-300);
}

.auth-input {
  width: 100%;
  padding: 14px 16px;
  border: 1px solid var(--gray-300);
  border-radius: var(--radius-md);
  font-size: 1rem;
  transition: var(--transition);
  margin-bottom: 16px;
}

.auth-input:focus {
  outline: none;
  border-color: var(--primary);
  box-shadow: 0 0 0 3px rgba(24, 104, 219, 0.1);
}

.auth-footer {
  margin-top: 24px;
  font-size: 0.875rem;
  color: var(--gray-600);
  text-align: center;
}

.auth-footer a {
  color: var(--primary);
  font-weight: 500;
}

.auth-sidebar {
  background: var(--gradient-primary);
  color: var(--white);
  padding: 48px;
  display: flex;
  flex-direction: column;
  justify-content: center;
}

.auth-sidebar blockquote {
  font-size: 1.5rem;
  line-height: 1.5;
  margin-bottom: 32px;
}

.auth-sidebar cite {
  font-style: normal;
}

.auth-sidebar cite strong {
  display: block;
  margin-top: 16px;
}

/* Cookie Banner */
.cookie-banner {
  position: fixed;
  bottom: 24px;
  left: 24px;
  right: 24px;
  background: var(--white);
  border-radius: var(--radius-lg);
  padding: 24px;
  box-shadow: var(--shadow-xl);
  z-index: 1001;
  max-width: 500px;
}

.cookie-banner h4 {
  margin-bottom: 8px;
}

.cookie-banner p {
  font-size: 0.875rem;
  color: var(--gray-600);
  margin-bottom: 16px;
}

.cookie-actions {
  display: flex;
  gap: 12px;
}

.cookie-banner .btn-sm {
  padding: 8px 16px;
}

/* Cookie Modal */
.modal-overlay {
  position: fixed;
  inset: 0;
  background: rgba(0,0,0,0.5);
  z-index: 1002;
  display: none;
  align-items: center;
  justify-content: center;
}

.modal-overlay.active {
  display: flex;
}

.modal {
  background: var(--white);
  border-radius: var(--radius-lg);
  padding: 32px;
  max-width: 500px;
  width: 90%;
  max-height: 80vh;
  overflow-y: auto;
}

.modal h3 {
  margin-bottom: 24px;
}

.cookie-category {
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding: 16px 0;
  border-bottom: 1px solid var(--gray-200);
}

.cookie-category h5 {
  font-size: 0.875rem;
}

.cookie-category p {
  font-size: 0.75rem;
  color: var(--gray-500);
  margin-top: 4px;
}

.toggle-switch {
  width: 48px;
  height: 24px;
  background: var(--gray-300);
  border-radius: 12px;
  position: relative;
  cursor: pointer;
  transition: var(--transition);
}

.toggle-switch.active {
  background: var(--primary);
}

.toggle-switch::after {
  content: '';
  position: absolute;
  width: 20px;
  height: 20px;
  background: var(--white);
  border-radius: 50%;
  top: 2px;
  left: 2px;
  transition: var(--transition);
}

.toggle-switch.active::after {
  left: 26px;
}

/* Responsive */
@media (max-width: 1024px) {
  .container {
    padding: 0 20px;
  }

  .nav-links {
    display: none;
  }

  .feature-highlight,
  .screen-recorder {
    grid-template-columns: 1fr;
  }

  .video-editor-grid,
  .integrations-grid {
    grid-template-columns: repeat(3, 1fr);
  }

  .security-grid,
  .use-cases-grid {
    grid-template-columns: repeat(2, 1fr);
  }

  .features-grid {
    grid-template-columns: repeat(2, 1fr);
  }

  .testimonials-grid,
  .pricing-cards {
    grid-template-columns: repeat(2, 1fr);
  }

  .footer-grid {
    grid-template-columns: repeat(2, 1fr);
  }

  .auth-container {
    grid-template-columns: 1fr;
  }

  .auth-sidebar {
    display: none;
  }
}

@media (max-width: 768px) {
  .section {
    padding: 60px 0;
  }

  h1 { font-size: 2rem; }
  h2 { font-size: 1.75rem; }

  .video-editor-grid,
  .integrations-grid,
  .features-grid,
  .testimonials-grid,
  .pricing-cards {
    grid-template-columns: 1fr;
  }

  .security-grid,
  .use-cases-grid,
  .enterprise-stats {
    grid-template-columns: 1fr;
  }

  .footer-grid {
    grid-template-columns: 1fr;
  }

  .footer-bottom {
    flex-direction: column;
    gap: 16px;
    text-align: center;
  }

  .pricing-controls {
    flex-direction: column;
  }
}
